package ru.truetv.launcher;
import android.app.*;import android.content.*;import android.os.*;import android.net.*;import android.widget.*;import android.view.*;import android.provider.*;import android.database.*;import java.io.*;import java.net.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import ru.truetv.bridge.*;
/** Actual receive popup / clipboard / explicit public TXT save; local authenticated client. VM only. */
public final class TextReceiveCheck extends Instrumentation {
 private Context c;private ShareSettingsActivity screen;private final ExecutorService pool=Executors.newCachedThreadPool();private final StringBuilder log=new StringBuilder();private int checks;private Identity phone,tv;private ClipData oldClip;private boolean oldAuto;private final Set<Uri> cleanup=new HashSet<>();private Set<Uri> before;private android.content.ClipboardManager clipboard;
 public void onCreate(Bundle b){super.onCreate(b);start();}private Object f(Object o,String n)throws Exception{Class<?> type=o.getClass();while(type!=null){try{Field x=type.getDeclaredField(n);x.setAccessible(true);return x.get(o);}catch(NoSuchFieldException missing){type=type.getSuperclass();}}throw new NoSuchFieldException(n);}private void main(Runnable a){runOnMainSync(a);waitForIdleSync();}private void check(boolean a,String text){log.append(a?"PASS ":"FAIL ").append(text).append('\n');checks++;if(!a)throw new AssertionError(text);}interface Wait{boolean ok()throws Exception;}private void until(Wait w)throws Exception{long end=SystemClock.uptimeMillis()+25000;while(!w.ok()&&SystemClock.uptimeMillis()<end){VmWindows.clear(this);Thread.sleep(70);}check(w.ok(),"await condition");}
 private Button button(String n)throws Exception{return (Button)f(screen,n);}private int port()throws Exception{Transfer.Receiver r=(Transfer.Receiver)f(screen,"receiver");return r==null?0:r.port();}
 private Future<Boolean> send(String value,boolean text){return pool.submit(()->{try(Transfer.Sender s=new Transfer.Sender()){byte[] bytes=SharedText.encode(value);Wire.Item item=text?SharedText.item(bytes):new Wire.Item("totv234-file-"+System.currentTimeMillis()+".txt","text/plain",bytes.length);s.send(phone,InetAddress.getLoopbackAddress(),port(),tv.fingerprint(),new Wire.Offer("Phone fixture",Arrays.asList(item)),i->new ByteArrayInputStream(bytes),new Transfer.ClientEvents(){public void waiting(String a,String b,String x){}public void accepted(String f){}public void update(int i,String n,long a,long b){}});return true;}catch(Exception e){log.append("SEND ").append(e.getClass().getSimpleName()).append('\n');return false;}});}
 private Set<Uri> downloads()throws Exception{Set<Uri> out=new HashSet<>();if(Build.VERSION.SDK_INT>=29){try(Cursor q=c.getContentResolver().query(MediaStore.Downloads.EXTERNAL_CONTENT_URI,new String[]{"_id","_display_name","is_pending"},null,null,null)){while(q!=null&&q.moveToNext())if(q.getInt(2)==0&&(q.getString(1).startsWith("Text-")||q.getString(1).startsWith("totv234-file-")))out.add(ContentUris.withAppendedId(MediaStore.Downloads.EXTERNAL_CONTENT_URI,q.getLong(0)));}}else{File[] all=Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS).listFiles();if(all!=null)for(File x:all)if(x.getName().startsWith("Text-")||x.getName().startsWith("totv234-file-"))out.add(Uri.fromFile(x));}return out;}
 private byte[] read(Uri uri)throws Exception{try(InputStream in="file".equals(uri.getScheme())?new FileInputStream(uri.getPath()):c.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
 public void onStart(){Bundle result=new Bundle();try{c=getTargetContext();if(!Build.FINGERPRINT.contains("generic")&&!Build.MODEL.contains("Android SDK"))throw new AssertionError("VM only");VmWindows.prepare(this);oldAuto=c.getSharedPreferences("totv_window",0).getBoolean("automatic",false);c.getSharedPreferences("totv_window",0).edit().putBoolean("automatic",false).commit();before=downloads();HomeActivity home=VmWindows.home(this);ActivityMonitor monitor=new ActivityMonitor(ShareSettingsActivity.class.getName(),null,false);addMonitor(monitor);main(()->home.header.getChildAt(2).performClick());screen=(ShareSettingsActivity)waitForMonitorWithTimeout(monitor,15000);removeMonitor(monitor);until(()->screen!=null&&port()>0);clipboard=(android.content.ClipboardManager)c.getSystemService(Context.CLIPBOARD_SERVICE);main(()->oldClip=clipboard.getPrimaryClip());tv=Identity.load(new File(c.getFilesDir(),"to-tv-identity"));phone=Identity.load(new File(c.getCacheDir(),"text234-phone"));String value="  vless://fixture@example.invalid:443?token=+%2F#Тест\r\nКод: 00123 😀\n"+new String(new char[8000]).replace('\0','Я')+"\n  ";Future<Boolean> request=send(value,true);until(()->f(screen,"decision")!=null);check(downloads().equals(before),"text creates no file before acceptance");check(((TextView)f(screen,"details")).getText().toString().contains("Text")||((TextView)f(screen,"details")).getText().toString().contains("Текст"),"incoming request explicitly says text");main(()->{try{button("accept").performClick();}catch(Exception e){throw new RuntimeException(e);}});check(request.get(40,TimeUnit.SECONDS),"real TLS shared text accepted");until(()->button("copyText").getVisibility()==View.VISIBLE);check(value.equals(f(screen,"receivedText")),"entire original text retained exactly");check(((TextView)f(screen,"details")).getText().length()<value.length(),"preview is bounded without truncating payload");check(downloads().equals(before),"text still not saved automatically");check(button("saveText").getVisibility()==View.VISIBLE&&button("open").getVisibility()==View.GONE&&button("location").getVisibility()==View.GONE,"text actions replace file actions");main(()->{try{button("copyText").performClick();}catch(Exception e){throw new RuntimeException(e);}});check(value.contentEquals(clipboard.getPrimaryClip().getItemAt(0).getText()),"clipboard has full exact Unicode/CRLF/link/code");Thread.sleep(900);android.graphics.Bitmap shot=getUiAutomation().takeScreenshot();if(shot!=null)try(OutputStream out=new FileOutputStream(new File(c.getExternalFilesDir(null),"2.2.4-text-api"+Build.VERSION.SDK_INT+".png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}
 main(()->{try{button("saveText").performClick();}catch(Exception e){throw new RuntimeException(e);}});until(()->(Boolean)f(screen,"textSaved"));Set<Uri> added=downloads();added.removeAll(before);cleanup.addAll(added);check(added.size()==1,"explicit Save creates exactly one TXT in Downloads");check(Arrays.equals(read(added.iterator().next()),SharedText.encode(value)),"saved TXT is exact UTF-8 without BOM or newline conversion");check(!button("saveText").isEnabled(),"completed Save prevents accidental duplicate click");
 main(()->{try{((CheckBox)f(screen,"automatic")).setChecked(true);}catch(Exception e){throw new RuntimeException(e);}});String code=" 00123-ABC \n";check(send(code,true).get(30,TimeUnit.SECONDS),"next text auto-accepted only in open window");until(()->code.equals(f(screen,"receivedText"))&&button("copyText").getVisibility()==View.VISIBLE);main(()->{try{button("copyText").performClick();}catch(Exception e){throw new RuntimeException(e);}});check(code.contentEquals(clipboard.getPrimaryClip().getItemAt(0).getText()),"second code copies exactly including spaces");check(downloads().size()==before.size()+1,"second text does not silently save");check(send("ordinary TXT contents",false).get(30,TimeUnit.SECONDS),"ordinary text/plain file accepted");until(()->button("open").getVisibility()==View.VISIBLE);check(button("copyText").getVisibility()==View.GONE&&button("saveText").getVisibility()==View.GONE,"actual .txt attachment stays in file mode");main(screen::finish);until(()->port()==0);check(!send("closed",true).get(12,TimeUnit.SECONDS),"closed window refuses text");result.putBoolean("passed",true);
 }catch(Throwable e){StringWriter w=new StringWriter();e.printStackTrace(new PrintWriter(w));log.append(w);result.putBoolean("passed",false);}finally{try{if(screen!=null)main(screen::finish);if(clipboard!=null)main(()->{if(oldClip!=null)clipboard.setPrimaryClip(oldClip);else if(Build.VERSION.SDK_INT>=28)clipboard.clearPrimaryClip();else clipboard.setPrimaryClip(ClipData.newPlainText("",""));});if(before!=null){Set<Uri> added=downloads();added.removeAll(before);cleanup.addAll(added);}for(Uri u:cleanup)if("file".equals(u.getScheme()))new File(u.getPath()).delete();else c.getContentResolver().delete(u,null,null);c.getSharedPreferences("totv_window",0).edit().putBoolean("automatic",oldAuto).commit();}catch(Exception e){log.append("CLEANUP ").append(e);}pool.shutdownNow();}result.putString("report",log+"Checks="+checks);finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
